TripleSphereCamera::TripleSphereCamera(
    int width, int height, double scale,
    double fx, double fy, double cx, double cy,
    double xi, double lambda, double alpha, double b, double c)
    : AbstractCamera(static_cast<int>(width * scale),
                     static_cast<int>(height * scale), scale),
      fx_(fx * scale),
      fy_(fy * scale),
      cx_(cx * scale),
      cy_(cy * scale),
      xi_(xi),
      lambda_(lambda),
      alpha_(alpha),
      b_(b * scale),
      c_(c * scale) {}

Vector2d TripleSphereCamera::world2cam(const Vector3d& p) const {
  const double d1 = p.norm();
  const double z2 = p.z() + xi_ * d1;
  const double d2 = std::sqrt(p.x() * p.x() + p.y() * p.y() + z2 * z2);
  const double z3 = z2 + lambda_ * d2;
  const double d3 = std::sqrt(p.x() * p.x() + p.y() * p.y() + z3 * z3);
  const double denominator = z3 + alpha_ / (1.0 - alpha_) * d3;
  if (!std::isfinite(denominator) || std::abs(denominator) < kEpsilon) {
    return Vector2d::Constant(std::numeric_limits<double>::quiet_NaN());
  }
  const double mx = p.x() / denominator;
  const double my = p.y() / denominator;
  return Vector2d(fx_ * mx + b_ * my + cx_,
                  c_ * mx + fy_ * my + cy_);

